@namespace sv_392fd49649ea4bda949cd4a4aeb5d1d6.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <div class="step-item @cssClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@namespace sv_392fd49649ea4bda949cd4a4aeb5d1d6.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
            <label class="form-label">Company Name *</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="e => UpdateEntry(Entry with { Company = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title *</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="e => UpdateEntry(Entry with { Title = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check mb-2">
                <input type="checkbox" class="form-check-input" id="current-@Index" checked="@IsCurrent"
                       @onchange="OnCurrentChanged" />
                <label class="form-check-label" for="current-@Index">Currently working here</label>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private async Task UpdateEntry(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { EndDate = isCurrent ? null : DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

@namespace sv_392fd49649ea4bda949cd4a4aeb5d1d6.Components.Pages.Apply

<div class="reference-form mb-3 p-3 border rounded">
    <div class="d-flex justify-content-between align-items-center mb-2">
        <h6 class="mb-0">Reference @(Index + 1)</h6>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row mb-2">
        <div class="col-md-6">
            <label class="form-label">Name *</label>
            <input type="text" class="form-control" value="@Ref.Name"
                   @onchange="e => Update(Ref with { Name = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Relationship *</label>
            <input type="text" class="form-control" value="@Ref.Relationship"
                   @onchange="e => Update(Ref with { Relationship = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="row">
        <div class="col-md-6">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" value="@Ref.Email"
                   @onchange="e => Update(Ref with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" value="@Ref.Phone"
                   @onchange="e => Update(Ref with { Phone = (string?)e.Value ?? "" })" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Reference Ref { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnRefChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnRefChanged.InvokeAsync(updated);
    }
}

