@using sv_392fd49649ea4bda949cd4a4aeb5d1d6.Services

<div class="step-content">
    <h4>Review & Submit</h4>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h5>Application Submitted Successfully!</h5>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="review-section mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Personal Information</h5>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@Personal.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@Personal.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@Personal.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@Personal.Address</dd>
                </dl>
            }
        </div>

        <div class="review-section mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Work History</h5>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <div class="review-section mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h5>References</h5>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email &middot; @r.Phone</small>
                    </div>
                }
            }
        </div>

        <div class="review-section mb-4">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Cover Letter</h5>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="ps-3" style="white-space: pre-wrap;">@CoverLetter</p>
        </div>

        <div class="d-flex justify-content-between">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
                @if (isSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }

    private string? ErrorMessage { get; set; }
