+@namespace sv_392fd49649ea4bda949cd4a4aeb5d1d6.Components.Pages.Apply
+@using sv_392fd49649ea4bda949cd4a4aeb5d1d6.Services
+
+<div class="step-content">
+    <h4>Personal Information</h4>
+
+    @if (!string.IsNullOrEmpty(ErrorMessage))
+    {
+        <div class="alert alert-danger">@ErrorMessage</div>
+    }
+
+    <div class="row mb-3">
+        <div class="col-md-6">
+            <label class="form-label">Full Name *</label>
+            <input type="text" class="form-control" value="@FullName"
+                   @onchange="e => FullName = (string?)e.Value ?? "" " />
+        </div>
+        <div class="col-md-6">
+            <label class="form-label">Email *</label>
+            <input type="email" class="form-control @(emailInvalid ? "is-invalid" : "")" value="@Email"
+                   @onchange="e => { Email = (string?)e.Value ?? ""; emailInvalid = false; }" />
+            @if (emailInvalid)
+            {
+                <div class="invalid-feedback">Please enter a valid email address.</div>
+            }
+        </div>
+    </div>
+
+    <div class="row mb-3">
+        <div class="col-md-6">
+            <label class="form-label">Phone *</label>
+            <input type="tel" class="form-control" value="@Phone"
+                   @onchange="e => Phone = (string?)e.Value ?? "" " />
+        </div>
+        <div class="col-md-6">
+            <label class="form-label">Address *</label>
+            <input type="text" class="form-control" value="@Address"
+                   @onchange="e => Address = (string?)e.Value ?? "" " />
+        </div>
+    </div>
+
+    <div class="d-flex justify-content-end">
+        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
+            @if (isValidating)
+            {
+                <span class="spinner-border spinner-border-sm me-1"></span>
+            }
+            Next
+        </button>
+    </div>
+</div>
+
+@code {
+    [Parameter] public PersonalInfo? Info { get; set; }
+    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
+
+    [Inject] private IApplicationService ApplicationService { get; set; } = default!;
+
+    private string FullName { get; set; } = "";
+    private string Email { get; set; } = "";
+    private string Phone { get; set; } = "";
+    private string Address { get; set; } = "";
+    private string? ErrorMessage { get; set; }
+    private bool emailInvalid;
+    private bool isValidating;
+
+    protected override void OnParametersSet()
+    {
+        if (Info is not null)
+        {
+            FullName = Info.FullName;
+            Email = Info.Email;
+            Phone = Info.Phone;
+            Address = Info.Address;
+        }
+    }
+
+    private async Task HandleNext()
+    {
+        ErrorMessage = null;
+        emailInvalid = false;
+
+        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
+            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
+        {
+            ErrorMessage = "All fields are required.";
+            return;
+        }
+
+        isValidating = true;
+        try
+        {
+            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
+            if (!emailValid)
+            {
+                emailInvalid = true;
+                ErrorMessage = "The email address is not valid.";
+                return;
+            }
+
+            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
+        }
+        finally
+        {
+            isValidating = false;
+        }
+    }
+}
