    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty });

    private Task OnStartDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        return UpdateEntry(Entry with { StartDate = date });
    }

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        return UpdateEntry(Entry with { EndDate = endDate });
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty });

    private async Task UpdateEntry(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { EndDate = isCurrent ? null : DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

